const input = $input.first().json;
const normalize = (value) => String(value || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLocaleLowerCase('fr-FR').replace(/\s+/g, ' ').trim();
const datePart = (value) => value ? String(value).slice(0, 10) : '';
const fingerprint = (row) => [row.normalized_title, row.declared_company_name, row.city || row.postal_code, row.contract_type, datePart(row.published_at)].map(normalize).join('|');
const rows = (input.normalized_rows || []).map((row) => {
  const sourceKey = row.offer_key || `${input.source}:${row.source_offer_id || 'missing'}`;
  const fp = row.dedupe_fingerprint || fingerprint(row);
  const previousSource = input.previous_by_source_key[sourceKey] || null;
  const previousGroup = input.previous_by_fingerprint[fp] || null;
  let dedupeStatus = 'new';
  let reason = 'G8N_DEDUP_NEW';
  let confidence = row.source_offer_id ? 1 : 0.5;
  let duplicateOf = null;
  let canonical = sourceKey;
  let republicationGroup = null;
  if (previousSource && previousSource.dedupe_fingerprint === fp) { dedupeStatus = 'duplicate'; reason = 'G8N_DEDUP_SAME_SOURCE_SAME_HASH'; duplicateOf = previousSource.offer_key || sourceKey; canonical = duplicateOf; }
  else if (previousSource) { dedupeStatus = 'updated'; reason = 'G8N_DEDUP_SAME_SOURCE_CHANGED_HASH'; canonical = previousSource.canonical_offer_key || sourceKey; }
  else if (previousGroup && previousGroup.declared_company_name === row.declared_company_name && (previousGroup.city === row.city || previousGroup.postal_code === row.postal_code)) { dedupeStatus = 'republication'; reason = 'G8N_DEDUP_FALLBACK_REPUBLICATION'; republicationGroup = `${input.source}:repub:${fp}`; canonical = previousGroup.canonical_offer_key || previousGroup.offer_key; confidence = 0.72; }
  else if (!row.source_offer_id) { reason = 'G8N_DEDUP_MISSING_SOURCE_ID'; confidence = 0.5; }
  const out = { ...row, dedupe_fingerprint: fp, canonical_offer_key: canonical, republication_group_key: republicationGroup, duplicate_of_offer_key: duplicateOf, dedupe_status: dedupeStatus, dedupe_reasons_json: JSON.stringify([reason]), dedupe_confidence: confidence, first_seen_at: previousSource?.first_seen_at || row.first_seen_at || new Date().toISOString(), last_seen_at: new Date().toISOString(), status: dedupeStatus === 'duplicate' ? 'duplicate' : row.status || 'active' };
  input.counters[dedupeStatus] = (input.counters[dedupeStatus] || 0) + 1;
  return out;
});
return [{ json: { ...input, deduped_job_offer_upserts: rows } }];
